// Endpoint is a function type representing a client-side RPC endpoint.
// It processes a request and returns a response or an error.
type Endpoint func(ctx context.Context, req, resp interface{}) error

// Middleware is a function that wraps an Endpoint to add additional behavior.
type Middleware func(next Endpoint) Endpoint

// MiddlewareBuilder builds a middleware with information from a context.
type MiddlewareBuilder func(ctx context.Context) Middleware

// Chain connects middlewares into a single middleware.
func Chain(mws ...Middleware) Middleware {
	return func(next Endpoint) Endpoint {
		for i := len(mws) - 1; i >= 0; i-- {
			next = mws[i](next)
		}
		return next
	}
}

