type StreamEndpoint func(ctx context.Context) (st streaming.ClientStream, err error)

// StreamRecvEndpoint is invoked on each message received from the stream.
type StreamRecvEndpoint func(ctx context.Context, stream streaming.ClientStream, message interface{}) (err error)

// EqualsTo checks if two StreamRecvEndpoint are equivalent for comparison purposes.
func (e StreamRecvEndpoint) EqualsTo(e2 StreamRecvEndpoint) bool {
	if e == nil && e2 == nil {
		return true
	}
	if e == nil || e2 == nil {
		return false
	}
	return &e == &e2
}

// StreamSendEndpoint is invoked on each message to be sent to the stream.
