// Package transport provides predefined transport protocol.
package transport

// Protocol indicates the transport protocol.
type Protocol int

// Predefined transport protocols.
const (
	PurePayload       Protocol = 0
	TTHeader          Protocol = 1 << iota
	Framed
	HTTP
	GRPC
	HESSIAN2
	_                                    // Reserved (was STREAMING)
	TTHeaderStreaming Protocol = 64      // Dedicated constant for TTHeader streaming
	GRPCStreaming     Protocol = 128     // Dedicated constant for gRPC streaming
	TTHeaderFramed            = TTHeader | Framed
)

// Unknown indicates the protocol is unknown.
const Unknown = "Unknown"

// String prints human readable information.
// For composite values, returns pipe-separated names of all set flags in ascending order of their bit values.
func (tp Protocol) String() string {
	// Handle single known protocols first
	switch tp {
	case PurePayload:
		return "PurePayload"
	case TTHeader:
		return "TTHeader"
	case Framed:
		return "Framed"
	case HTTP:
		return "HTTP"
	case GRPC:
		return "GRPC"
	case HESSIAN2:
		return "Hessian2"
	case TTHeaderStreaming:
		return "TTHeaderStreaming"
	case GRPCStreaming:
		return "GRPCStreaming"
	}

	// Handle composite protocols - check bits in ascending order
	var parts []string

	// Check each protocol bit in order: TTHeader(1), Framed(2), HTTP(4), GRPC(8), HESSIAN2(16), TTHeaderStreaming(64), GRPCStreaming(128)
	if tp&TTHeader != 0 {
		parts = append(parts, "TTHeader")
	}
	if tp&Framed != 0 {
		parts = append(parts, "Framed")
	}
	if tp&HTTP != 0 {
		parts = append(parts, "HTTP")
	}
	if tp&GRPC != 0 {
		parts = append(parts, "GRPC")
	}
	if tp&HESSIAN2 != 0 {
		parts = append(parts, "Hessian2")
	}
	if tp&TTHeaderStreaming != 0 {
		parts = append(parts, "TTHeaderStreaming")
	}
	if tp&GRPCStreaming != 0 {
		parts = append(parts, "GRPCStreaming")
	}

	if len(parts) > 0 {
		result := ""
		for i, part := range parts {
			if i > 0 {
				result += "|"
			}
			result += part
		}
		return result
	}

	return Unknown
}
